(defn starter-rules
  "Parses the built-in starter rules EDN vector."
  {:malli/schema [:=> [:cat] [:vector :map]] :cost/ticks 5000000}
  []
  (let [v (edn/read-string starter-rules-edn)]
    (if (vector? v) v [])))
